const output = items.map(item => {
  const data = item.json;

  return {
    json: {
      taskName: data.name || "No task name",
      dueDate: data.due_date ? new Date(parseInt(data.due_date)).toLocaleDateString() : "No due date",
      assignee: data.assignees?.[0]?.username || "Unassigned",
      projectName: data.project?.name || "No project",
      listName: data.list?.name || "No list",
      taskLink: data.url || "No link",
      priority: data.priority?.priority || "No priority",
      status: data.status?.status || "No status"
    }
  };
});

return output;

// Loop through all incoming calendar events
return items.map(item => {
  const data = item.json;

  // Extract attendees' emails dynamically
  const attendees = (data.attendees || []).map(a => a.email);

  // Format start and end times
  const formatDate = (dateObj) => {
    if (!dateObj?.dateTime || !dateObj?.timeZone) return null;
    const date = new Date(dateObj.dateTime);
    return `${date.toISOString().slice(0, 16).replace('T', ' ')} (${dateObj.timeZone})`;
  };

  return {
    json: {
      event_id: data.id,
      summary: data.summary || '',
      attendees,
      start: formatDate(data.start),
      end: formatDate(data.end),
    }
  };
});

function formatMeetingsForEmail(meetings) {
  const formatTime = (date) =>
    new Date(date).toLocaleTimeString("en-US", {
      hour: "numeric",
      minute: "2-digit",
    });

  const meetingRows = meetings.map((item, index) => {
    const output = item.json.output;
    const title = output.title;
    const start = output["start time"];
    const end = output["end time"];
    const attendees = output.attendees.map(a => `<li>${a.email}</li>`).join("");
    const prepNote = output["prep note"];

    return `
      <tr style="border-bottom: 1px solid #eee;">
        <td style="padding: 20px;">
          <h3 style="margin: 0; color: #2c3e50;">${index + 1}. ${title}</h3>
          <p style="margin: 5px 0;"><strong>🕒 Time:</strong> ${formatTime(start)} – ${formatTime(end)}</p>
          <p style="margin: 5px 0;"><strong>👥 Attendees:</strong></p>
          <ul style="margin-top: 5px; padding-left: 20px;">${attendees}</ul>
          ${prepNote ? `<p style="margin: 5px 0;"><strong>📝 Prep Note:</strong> ${prepNote}</p>` : ""}
        </td>
      </tr>
    `;
  }).join("");

  const htmlBody = `
    <div style="font-family: 'Segoe UI', Roboto, sans-serif; color: #333; max-width: 800px; margin: auto;">
      <h2 style="border-bottom: 2px solid #ddd; padding-bottom: 10px; color: #2c3e50;">👋 Hello there, here is your schedule for today:</h2>
      <h3 style="color: #2c3e50;">🗓️ Meetings</h3>
      <table style="width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 15px;">
        <tbody>
          ${meetingRows}
        </tbody>
      </table>
      <p style="margin-top: 30px; font-size: 13px; color: #999;">This is an automated meeting schedule summary for your day.</p>
    </div>
  `;

  return htmlBody.trim();
}

const formattedHtml = formatMeetingsForEmail(items);

return [
  {
    json: {
      message: formattedHtml
    }
  }
];

function getPriorityColor(priority) {
  switch (priority?.toLowerCase()) {
    case 'urgent': return '#d9534f'; // red
    case 'high': return '#f0ad4e';   // orange
    case 'normal': return '#5bc0de'; // blue
    case 'low': return '#5cb85c';    // green
    default: return '#999';          // grey
  }
}

function getStatusColor(status) {
  switch (status?.toLowerCase()) {
    case 'to do': return '#777';
    case 'in progress': return '#0275d8';
    case 'review': return '#f0ad4e';
    case 'complete':
    case 'done': return '#5cb85c';
    default: return '#bbb';
  }
}

const rows = items.map((item, index) => {
  const t = item.json;
  const priorityColor = getPriorityColor(t.priority);
  const statusColor = getStatusColor(t.status);

  return `
    <tr style="border-bottom: 1px solid #eee;">
      <td style="padding: 12px;">${index + 1}</td>
      <td style="padding: 12px;">${t.taskName}</td>
      <td style="padding: 12px;">${t.dueDate}</td>
      <td style="padding: 12px;">${t.assignee}</td>
      <td style="padding: 12px;">${t.projectName} → ${t.listName}</td>
      <td style="padding: 12px;">
        <span style="background-color: ${priorityColor}; color: white; padding: 4px 8px; border-radius: 4px; font-size: 12px;">
          ${t.priority}
        </span>
      </td>
      <td style="padding: 12px;">
        <span style="background-color: ${statusColor}; color: white; padding: 4px 8px; border-radius: 4px; font-size: 12px;">
          ${t.status}
        </span>
      </td>
      <td style="padding: 12px;"><a href="${t.taskLink}" style="color: #0275d8; text-decoration: none;">View Task</a></td>
    </tr>
  `;
}).join('');

const emailBody = `
  <div style="font-family: 'Segoe UI', Roboto, sans-serif; color: #333; max-width: 800px; margin: auto;">
    <h2 style="border-bottom: 2px solid #ddd; padding-bottom: 10px; color: #2c3e50;">📝 Task Summary</h2>
    <table style="width: 100%; border-collapse: collapse; margin-top: 20px; font-size: 14px;">
      <thead>
        <tr style="background-color: #f8f9fa;">
          <th style="text-align: left; padding: 12px;">#</th>
          <th style="text-align: left; padding: 12px;">Task</th>
          <th style="text-align: left; padding: 12px;">Due Date</th>
          <th style="text-align: left; padding: 12px;">Assignee</th>
          <th style="text-align: left; padding: 12px;">Project</th>
          <th style="text-align: left; padding: 12px;">Priority</th>
          <th style="text-align: left; padding: 12px;">Status</th>
          <th style="text-align: left; padding: 12px;">Link</th>
        </tr>
      </thead>
      <tbody>
        ${rows}
      </tbody>
    </table>
    <p style="margin-top: 30px; font-size: 13px; color: #999;">This is an automated summary of your current task assignments.</p>
  </div>
`;

return [
  {
    json: {
      emailBody
    }
  }
];
